/* Local icon sprite loader. Replaces <i data-lucide="x"> with
 *   <svg ...><use href="/static/vendor/icons.svg#x"></use></svg>
 * and keeps the old `lucide.createIcons()` call sites working (window.lucide shim), so markup that JS
 * builds at runtime needs no change. The sprite is generated by scripts/build_icons_sprite.cjs. */
(function () {
  'use strict';
  var SPRITE = '/static/vendor/icons.svg';
  var NS = 'http://www.w3.org/2000/svg';
  var XLINK = 'http://www.w3.org/1999/xlink';
  var legacyCreateIcons = window.lucide && window.lucide.createIcons;

  function build(el, name) {
    var svg = document.createElementNS(NS, 'svg');
    for (var i = 0; i < el.attributes.length; i++) {
      var a = el.attributes[i];
      if (a.name !== 'class') svg.setAttribute(a.name, a.value);
    }
    svg.setAttribute('xmlns', NS);
    svg.setAttribute('width', el.getAttribute('width') || '24');
    svg.setAttribute('height', el.getAttribute('height') || '24');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', 'none');
    svg.setAttribute('stroke', 'currentColor');
    svg.setAttribute('stroke-width', '2');
    svg.setAttribute('stroke-linecap', 'round');
    svg.setAttribute('stroke-linejoin', 'round');
    svg.setAttribute('class', ('lucide lucide-' + name + ' ' + (el.getAttribute('class') || '')).trim());
    if (!svg.hasAttribute('aria-label') && !svg.hasAttribute('aria-labelledby') && !svg.hasAttribute('role')) {
      svg.setAttribute('aria-hidden', 'true');
    }
    svg.setAttribute('focusable', 'false');
    var use = document.createElementNS(NS, 'use');
    use.setAttribute('href', SPRITE + '#' + name);
    use.setAttributeNS(XLINK, 'xlink:href', SPRITE + '#' + name);
    svg.appendChild(use);
    return svg;
  }

  function createIcons(root) {
    // Preserve the bundled library as a fallback if SVG <use> is unavailable.
    if (typeof SVGUseElement === 'undefined' && typeof legacyCreateIcons === 'function') {
      legacyCreateIcons();
      return;
    }
    var scope = root && root.querySelectorAll ? root : document;
    var nodes = scope.querySelectorAll('[data-lucide]');
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      var name = el.getAttribute('data-lucide');
      if (!name) continue;
      var href = SPRITE + '#' + name;
      if (el.namespaceURI === NS && el.localName === 'svg') {
        var use = el.querySelector('use');
        if (use && use.getAttribute('href') === href) continue;
        // JS flipped data-lucide on an already converted icon: re-point it.
        el.setAttribute('class', el.getAttribute('class').replace(/lucide-[a-z0-9-]+/, 'lucide-' + name));
        if (use) { use.setAttribute('href', href); use.setAttributeNS(XLINK, 'xlink:href', href); }
        else el.appendChild(build(el, name).firstChild);
        continue;
      }
      if (el.parentNode) el.parentNode.replaceChild(build(el, name), el);
    }
  }

  window.lucide = window.lucide || {};
  window.lucide.createIcons = createIcons;
  window.lucide.iconSprite = SPRITE;

  var pending = false;
  function schedule() {
    if (pending) return;
    pending = true;
    Promise.resolve().then(function () { pending = false; createIcons(); });
  }
  function start() {
    createIcons();
    if (typeof MutationObserver === 'function') {
      new MutationObserver(schedule).observe(document.body, {
        childList: true, subtree: true, attributes: true, attributeFilter: ['data-lucide'],
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
